const list=document.getElementById('list');
const countEl=document.getElementById('count');
const emptyEl=document.getElementById('empty');
const clearBtn=document.getElementById('clearBtn');
const msg=document.getElementById('msg');
const input=document.getElementById('newItem');
let items=[];let revs={};

function render(){
  list.textContent='';
  for(const it of items){
    const li=document.createElement('li');
    if(it.done)li.className='done';
    const lab=document.createElement('label');
    const cb=document.createElement('input');
    cb.type='checkbox';cb.checked=!!it.done;
    const sp=document.createElement('span');sp.textContent=it.name;
    cb.addEventListener('change',()=>toggle(it.id,cb.checked));
    lab.appendChild(cb);lab.appendChild(sp);li.appendChild(lab);list.appendChild(li);
  }
  const left=items.filter(i=>!i.done).length;
  const anyDone=items.some(i=>i.done);
  countEl.textContent=items.length?(left===0?'All done!':left+' of '+items.length+' left to get'):'';
  emptyEl.hidden=items.length>0;
  clearBtn.hidden=!anyDone;
}

async function load(){
  try{
    const r=await tessera.call('data.read',{});
    items=r.data.items||[];revs=(r.revisions&&r.revisions.items)||{};
    render();
  }catch(e){msg.textContent='Could not load the list. Please try again.';}
}

async function toggle(id,done){
  try{
    await tessera.call('data.patch',{operations:[{op:'replace',collection:'items',id:id,revisionCount:revs[id],fields:{done:done}}]});
    msg.textContent='';
  }catch(e){msg.textContent='Could not update that item. The list was refreshed.';}
  await load();
}

document.getElementById('addForm').addEventListener('submit',async ev=>{
  ev.preventDefault();
  const name=input.value.trim();
  if(!name){msg.textContent='Type an item to add.';return;}
  try{
    await tessera.call('data.patch',{operations:[{op:'add',collection:'items',record:{name:name,done:false}}]});
    input.value='';msg.textContent='Added '+name+'.';
  }catch(e){msg.textContent='Could not add the item. What you typed is still here.';return;}
  await load();input.focus();
});

clearBtn.addEventListener('click',async()=>{
  const ops=items.filter(i=>i.done).map(i=>({op:'remove',collection:'items',id:i.id,revisionCount:revs[i.id]}));
  if(!ops.length)return;
  try{
    await tessera.call('data.patch',{operations:ops});
    msg.textContent='Removed '+ops.length+' ticked item'+(ops.length>1?'s':'')+'.';
  }catch(e){msg.textContent='Could not remove the items.';}
  await load();
});

load();

