const COLS=[{id:'todo',name:'To do'},{id:'doing',name:'Doing'},{id:'done',name:'Done'}];
let cards=[],revs={};
const board=document.getElementById('board');
const msg=document.getElementById('msg');
const input=document.getElementById('newTitle');
let focusKey=null;

async function load(){
  const r=await tessera.call('data.read',{});
  cards=Array.isArray(r.data.cards)?r.data.cards:[];
  revs=(r.revisions&&r.revisions.cards)||{};
  render();
}
function say(t){msg.textContent=t}
async function patch(ops,okText){
  try{await tessera.call('data.patch',{operations:ops});await load();say(okText)}
  catch(e){say('That did not work. Nothing was changed; please try again.');await load()}
}
function moveCard(c,to){
  if(c.column===to)return;
  const name=COLS.find(x=>x.id===to).name;
  patch([{op:'replace',collection:'cards',id:c.id,revisionCount:revs[c.id],fields:{column:to}}],'Moved "'+c.title+'" to '+name+'.');
}
function render(){
  board.textContent='';
  for(const col of COLS){
    const sec=document.createElement('section');
    sec.className='col';
    sec.setAttribute('aria-labelledby','h-'+col.id);
    const h=document.createElement('h2');h.id='h-'+col.id;
    const list=cards.filter(c=>c.column===col.id);
    h.textContent=col.name+' ('+list.length+')';
    sec.appendChild(h);
    const ul=document.createElement('ul');
    if(!list.length){const li=document.createElement('li');li.className='empty';li.textContent='No cards here.';ul.appendChild(li)}
    for(const c of list){
      const li=document.createElement('li');li.className='card';li.draggable=true;
      li.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',c.id)});
      const p=document.createElement('p');p.textContent=c.title;li.appendChild(p);
      const acts=document.createElement('div');acts.className='acts';
      const idx=COLS.findIndex(x=>x.id===col.id);
      if(idx>0){const b=document.createElement('button');b.type='button';b.textContent='← '+COLS[idx-1].name;b.setAttribute('aria-label','Move "'+c.title+'" to '+COLS[idx-1].name);b.addEventListener('click',()=>moveCard(c,COLS[idx-1].id));acts.appendChild(b)}
      if(idx<2){const b=document.createElement('button');b.type='button';b.textContent=COLS[idx+1].name+' →';b.setAttribute('aria-label','Move "'+c.title+'" to '+COLS[idx+1].name);b.addEventListener('click',()=>moveCard(c,COLS[idx+1].id));acts.appendChild(b)}
      const d=document.createElement('button');d.type='button';d.textContent='Delete';d.setAttribute('aria-label','Delete "'+c.title+'"');
      d.addEventListener('click',()=>{if(confirm('Delete "'+c.title+'"?')){patch([{op:'remove',collection:'cards',id:c.id,revisionCount:revs[c.id]}],'Deleted "'+c.title+'".')}});
      acts.appendChild(d);
      li.appendChild(acts);ul.appendChild(li);
    }
    sec.appendChild(ul);
    sec.addEventListener('dragover',e=>{e.preventDefault();sec.classList.add('over')});
    sec.addEventListener('dragleave',()=>sec.classList.remove('over'));
    sec.addEventListener('drop',e=>{e.preventDefault();sec.classList.remove('over');const id=e.dataTransfer.getData('text/plain');const c=cards.find(x=>x.id===id);if(c)moveCard(c,col.id)});
    board.appendChild(sec);
  }
}
document.getElementById('addForm').addEventListener('submit',e=>{
  e.preventDefault();
  const t=input.value.trim();
  if(!t){say('Type a title for the card first.');input.focus();return}
  input.value='';
  patch([{op:'add',collection:'cards',record:{title:t,column:'todo'}}],'Added "'+t+'" to To do.');
});
load();
